INSERT INTO FOOD (food_id, food_name, category, description, unit, storage_requirement, is_perishable) VALUES
  (1, 'Fresh Whole Wheat Phulka / Chapati Packs (10-Pack)', 'BAKERY', 'Soft handmade whole wheat flatbreads, zero preservatives. Ideal for shelter lunch and dinner meals.', 'packets', 'AMBIENT', TRUE),
  (2, 'Iyengar Bakery Masala Bread & Veg Puffs', 'BAKERY', 'Traditional Bangalore spiced onion-coriander bread loaves and potato vegetable curry puffs.', 'packets', 'AMBIENT', TRUE),
  (3, 'Tandoori Roti & Naan Catering Trays', 'BAKERY', 'Clay-oven baked whole wheat rotis and leavened naans from wedding reception banquet overflow.', 'packets', 'AMBIENT', TRUE),
  (4, 'Malabar Parotta Multi-Packs', 'BAKERY', 'Flaky layered Kerala parotta flatbreads, high-calorie meal staple for relief feeding.', 'packets', 'AMBIENT', TRUE),
  (5, 'Soft Bakery Pav Buns (12-Pack)', 'BAKERY', 'Freshly baked fluffy dinner pav buns for community vegetable curry and soup distribution.', 'packets', 'AMBIENT', TRUE),
  (6, 'Fresh Malai Paneer Blocks (1kg)', 'DAIRY', 'Vacuum-sealed fresh cottage cheese blocks packed with vegetarian milk protein and calcium.', 'kg', 'REFRIGERATED', TRUE),
  (7, 'Nandini Pasteurized Toned Milk Pouches', 'DAIRY', 'Fresh pasteurized cow milk sachets (1 Litre each) from Karnataka Milk Federation. Cold chain required.', 'litres', 'REFRIGERATED', TRUE),
  (8, 'Fresh Set Dahi / Curd Tubs (500g)', 'DAIRY', 'Probiotic-rich thick pasteurized fermented yogurt tubs. Essential for cooling midday meals.', 'packets', 'REFRIGERATED', TRUE),
  (9, 'Amul Salted Dairy Butter Bricks (500g)', 'DAIRY', 'Pure pasteurized cow milk table butter blocks. Essential fats and energy for community kitchens.', 'kg', 'REFRIGERATED', TRUE),
  (10, 'Spiced Masala Buttermilk / Chaas Pouches (200ml)', 'DAIRY', 'Cooling probiotic spiced buttermilk with ginger and curry leaves for summer hydration relief.', 'packets', 'REFRIGERATED', TRUE),
  (11, 'Fresh Khoya / Mawa Solid Milk Blocks', 'DAIRY', 'Evaporated dense milk solids for high-calorie festive nutrition and children dessert enrichment.', 'kg', 'REFRIGERATED', TRUE),
  (12, 'Organic Palak (Spinach) & Methi Greens', 'PRODUCE', 'Freshly harvested leafy greens rich in iron, vitamin A, and dietary fiber from peri-urban farms.', 'kg', 'REFRIGERATED', TRUE),
  (13, 'Country Tomatoes & Red Onions (Bulk Sacks)', 'PRODUCE', 'Essential cooking produce in 20kg crates from local APMC mandi. Firm and ripe staple vegetables.', 'kg', 'AMBIENT', TRUE),
  (14, 'Fresh Ginger-Garlic Cooking Paste Tubs', 'PRODUCE', 'Pure ground ginger and garlic aromatics for high-volume community soup kitchen preparations.', 'kg', 'REFRIGERATED', FALSE),
  (15, 'Farm Fresh Green Peas & Cauliflower Florets', 'PRODUCE', 'Tender sweet green peas and crisp cauliflower rich in vitamin C and plant protein.', 'kg', 'REFRIGERATED', TRUE),
  (16, 'Green Bell Peppers & Carrots Crates', 'PRODUCE', 'Crunchy farm carrots and sweet capsicum peppers for mixed vegetable curries and salads.', 'kg', 'AMBIENT', TRUE),
  (17, 'Ripe Bananas & Seasonal Papaya Crates', 'PRODUCE', 'Natural sweet potassium-rich fruits for children morning nutrition and shelter breakfast.', 'kg', 'AMBIENT', TRUE),
  (18, 'Hyderabadi Vegetable Dum Biryani Trays', 'PREPARED_MEALS', 'Aromatic long-grain basmati rice cooked with seasonal vegetables, mint, and saffron spices.', 'servings', 'REFRIGERATED', TRUE),
  (19, 'Homestyle Tadka Dal & Jeera Rice', 'PREPARED_MEALS', 'Nutritious yellow moong-toor lentil stew tempered with cumin, ghee, and steamed basmati rice.', 'servings', 'REFRIGERATED', TRUE),
  (20, 'South Indian Sambar & Steamed Idlis', 'PREPARED_MEALS', 'Steamed fluffy fermented rice-lentil idlis served with hot drumstick and vegetable tamarind stew.', 'servings', 'REFRIGERATED', TRUE),
  (21, 'Paneer Butter Masala Catering Trays', 'PREPARED_MEALS', 'Rich cashew-tomato gravy with soft paneer cottage cheese cubes prepared for banquet dinner event.', 'servings', 'REFRIGERATED', TRUE),
  (22, 'Punjabi Rajma Masala & Steamed Basmati Rice', 'PREPARED_MEALS', 'Slow-cooked red kidney beans in thick spiced onion-tomato gravy with fragrant basmati rice.', 'servings', 'REFRIGERATED', TRUE),
  (23, 'Chole Masala & Poori Banquet Packs', 'PREPARED_MEALS', 'Spiced chickpea curry packed with iron and protein, served with whole wheat puffed pooris.', 'servings', 'REFRIGERATED', TRUE),
  (24, 'Vegetable Pulao & Cucumber Boondi Raita', 'PREPARED_MEALS', 'Mildly spiced garden vegetable rice pilaf accompanied by cooling seasoned yogurt raita.', 'servings', 'REFRIGERATED', TRUE),
  (25, 'Moong Dal Khichdi Nutritious Healing Meal', 'PREPARED_MEALS', 'Comforting yellow split lentil and rice porridge cooked with cumin, ginger, and turmeric.', 'servings', 'REFRIGERATED', TRUE),
  (26, 'Fermented Idli & Dosa Wet Batter Tubs (1kg)', 'PREPARED_MEALS', 'Ready-to-cook fermented stone-ground rice and urad dal batter for breakfast feeding programs.', 'packets', 'REFRIGERATED', TRUE),
  (27, 'Sona Masoori Raw Rice (25kg Sacks)', 'CANNED_GOODS', 'Premium Karnataka medium-grain polished white rice. High yield and long shelf-life staple for hunger relief.', 'packets', 'AMBIENT', FALSE),
  (28, 'Unpolished Toor Dal & Chana Dal (10kg Bags)', 'CANNED_GOODS', 'High-protein staple yellow lentils and split chickpeas for high-volume shelter nutrition.', 'packets', 'AMBIENT', FALSE),
  (29, 'Whole Wheat Sharbati Atta Flour (10kg Sacks)', 'CANNED_GOODS', 'Stone-ground 100% whole grain wheat flour for community roti and chapati baking.', 'packets', 'AMBIENT', FALSE),
  (30, 'Dried Kabuli Chana Chickpeas & Raw Rajma (5kg)', 'CANNED_GOODS', 'Bulk raw garbanzo beans and red kidney beans. Shelf-stable vegetarian plant protein.', 'packets', 'AMBIENT', FALSE),
  (31, 'Thick Poha Flattened Rice Flakes (5kg Sacks)', 'CANNED_GOODS', 'Iron-rich dry parboiled flattened rice for instant high-volume breakfast porridge cooking.', 'packets', 'AMBIENT', FALSE),
  (32, 'Roasted Peanut & Jaggery Chikki Bars', 'PACKAGED_SNACKS', 'Traditional high-energy roasted groundnut and unrefined jaggery brittle bars. Compact emergency nutrition.', 'packets', 'AMBIENT', FALSE),
  (33, 'Millet Ragi Sweet Biscuit Packs', 'PACKAGED_SNACKS', 'Finger millet baked biscuits with natural jaggery. Rich in calcium and iron for youth shelters.', 'packets', 'AMBIENT', FALSE),
  (34, 'Spiced Roasted Makhana / Foxnuts Packs', 'PACKAGED_SNACKS', 'Light puffed lotus seeds roasted with turmeric and sea salt. Low-sodium, high-fiber healthy snack.', 'packets', 'AMBIENT', FALSE),
  (35, 'Artisan Sourdough Country Bread Loaves', 'BAKERY', 'Naturally fermented whole wheat sourdough bread with crusty crumb and gut-healthy prebiotic enzymes.', 'packets', 'AMBIENT', TRUE),
  (36, 'Whole Grain Multigrain Sandwich Bread', 'BAKERY', 'Pre-sliced fiber-rich sandwich loaves baked with flaxseeds, oats, sunflower seeds, and whole wheat.', 'packets', 'AMBIENT', TRUE),
  (37, 'Fresh Baked Butter Croissants (6-Pack)', 'BAKERY', 'Flaky French golden crescent pastries laminated with real churned butter for morning shelter meals.', 'packets', 'AMBIENT', TRUE),
  (38, 'French Crusty Baguettes & Dinner Rolls', 'BAKERY', 'Traditional artisan European crusty bread sticks and dinner brioche rolls from hotel banquet.', 'packets', 'AMBIENT', TRUE),
  (39, 'Natural Cheddar Cheese Blocks (1kg)', 'DAIRY', 'Aged pasteurized yellow cheddar cheese blocks rich in concentrated dairy protein, fat, and calcium.', 'kg', 'REFRIGERATED', TRUE),
  (40, 'Unsweetened Greek Style Plain Yogurt Tubs', 'DAIRY', 'Strained high-protein thick European yogurt packed with live probiotics and zero added sugar.', 'packets', 'REFRIGERATED', TRUE),
  (41, 'Fresh Crisp Gala Apples & Valencia Oranges (Crates)', 'PRODUCE', 'Grade-A fresh orchard fruits rich in vitamin C, flavonoids, and dietary fiber for child nutrition.', 'kg', 'AMBIENT', TRUE),
  (42, 'Iceberg Lettuce & Fresh Baby Salad Greens', 'PRODUCE', 'Hydroponic crisp lettuce, arugula, and baby spinach washed and packed for cold distribution.', 'kg', 'REFRIGERATED', TRUE),
  (43, 'Button Mushrooms & Zucchini Crates', 'PRODUCE', 'Fresh white button mushrooms and green courgettes rich in minerals and antioxidants.', 'kg', 'REFRIGERATED', TRUE),
  (44, 'Baked Penne Pasta in Basil Marinara Sauce', 'PREPARED_MEALS', 'Durum wheat penne rigate pasta tossed with crushed Italian plum tomatoes, garlic, oregano, and olive oil.', 'servings', 'REFRIGERATED', TRUE),
  (45, 'Creamy Herb & Mushroom Risotto Trays', 'PREPARED_MEALS', 'Arborio short-grain rice gently simmered in vegetable stock with sauteed wild mushrooms and parmesan.', 'servings', 'REFRIGERATED', TRUE),
  (46, 'Hearty Minestrone Vegetable & Bean Soup', 'PREPARED_MEALS', 'Warm comforting rustic vegetable broth with cannellini white beans, diced carrots, zucchini, and macaroni.', 'servings', 'REFRIGERATED', TRUE),
  (47, 'Canned Peeled Italian Plum Tomatoes & Puree', 'CANNED_GOODS', 'Whole peeled plum tomatoes in thick rich culinary sauce. Shelf-stable base for soup kitchens.', 'packets', 'AMBIENT', FALSE),
  (48, 'Rolled Porridge Oats & Whole Grain Muesli (5kg)', 'CANNED_GOODS', 'High-fiber whole grain rolled breakfast oats and toasted seed muesli for nutritious morning shelter porridge.', 'packets', 'AMBIENT', FALSE);
